<script setup lang="ts">
import type {Row} from '~/utils/resources'
const csv=ref(''),preview=ref<Row|null>(null),error=ref(''),busy=ref(false),done=ref('')
async function file(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(f){csv.value=await f.text();preview.value=null;done.value=''}}
async function submit(commit=false){busy.value=true;error.value='';try{const r=await useApi()<Row>('/import/subscriptions',{method:'POST',body:{csv:csv.value,commit}});if(commit){done.value=`Imported ${r.created} subscriptions; ${r.skipped} rows skipped.`;preview.value=null;csv.value=''}else preview.value=r}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><div class="page"><div class="page-head"><div><h1>Import subscriptions</h1><p>Move your spreadsheet into a validated subscription workflow.</p></div><UButton to="/samples/subscriptions-import.csv" external download variant="outline">Download sample</UButton></div><UCard><UAlert v-if="error" color="error" :title="error" class="mb-4"/><UAlert v-if="done" color="success" :title="done" class="mb-4"/><label class="block text-sm font-medium mb-3" for="import-file">Choose a CSV file</label><input id="import-file" type="file" accept=".csv,text/csv" class="block w-full text-sm mb-5 file:mr-4 file:rounded-lg file:border-0 file:px-4 file:py-2 file:bg-violet-100 file:text-violet-800" @change="file"/><UButton :disabled="!csv" :loading="busy" @click="submit()">Validate file</UButton><template v-if="preview"><div class="flex justify-between items-center mt-6 mb-4"><p>{{preview.valid}} valid rows of {{preview.total}}</p><UButton :disabled="!preview.valid" :loading="busy" @click="submit(true)">Import {{preview.valid}} subscriptions</UButton></div><div v-for="r in preview.rows" :key="r.row" class="flex justify-between gap-4 py-3 border-b border-default text-sm"><span>Row {{r.row}} · {{r.raw.customer_name}}</span><span :class="r.errors.length?'text-error':'text-success'">{{r.errors.length?r.errors.join('; '):'Ready'}}</span></div></template></UCard></div></template>
